package com.example.canasta.data.remote

import com.example.canasta.data.remote.api.ProductApiService
import com.example.canasta.data.remote.interceptors.AuthInterceptor
import com.jakewharton.retrofit2.converter.kotlinx.serialization.asConverterFactory
import kotlinx.serialization.json.Json
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.OkHttpClient
import okhttp3.logging.HttpLoggingInterceptor
import retrofit2.Retrofit
import java.util.concurrent.TimeUnit

/**
 * Cliente singleton para configurar Retrofit y OkHttp
 * Proporciona acceso a los servicios de API
 */
object ApiClient {

    // URL base del servidor
    private const val BASE_URL = "http://localhost:8080/"

    // Configuración de kotlinx-serialization JSON
    private val json = Json {
        ignoreUnknownKeys = true // Ignora campos desconocidos del JSON
        isLenient = true // Permite JSON menos estricto
        coerceInputValues = true // Maneja valores nulos de forma más flexible
    }

    // Interceptor de autenticación (se puede acceder para setear el token)
    val authInterceptor = AuthInterceptor()

    // Cliente OkHttp configurado con interceptors
    private val okHttpClient: OkHttpClient by lazy {
        val loggingInterceptor = HttpLoggingInterceptor().apply {
            level = HttpLoggingInterceptor.Level.BODY
        }

        OkHttpClient.Builder()
            .addInterceptor(authInterceptor) // Añade autenticación
            .addInterceptor(loggingInterceptor) // Añade logging
            .connectTimeout(30, TimeUnit.SECONDS)
            .readTimeout(30, TimeUnit.SECONDS)
            .writeTimeout(30, TimeUnit.SECONDS)
            .build()
    }

    // Instancia de Retrofit configurada
    private val retrofit: Retrofit by lazy {
        Retrofit.Builder()
            .baseUrl(BASE_URL)
            .client(okHttpClient)
            .addConverterFactory(json.asConverterFactory("application/json".toMediaType()))
            .build()
    }

    // Servicio de API para productos
    val productService: ProductApiService by lazy {
        retrofit.create(ProductApiService::class.java)
    }

    /**
     * Método de conveniencia para establecer el token de autenticación
     * @param token Token JWT de autenticación
     */
    fun setAuthToken(token: String?) {
        authInterceptor.setToken(token)
    }

    /**
     * Obtiene el token actual
     */
    fun getAuthToken(): String? = authInterceptor.getToken()
}

package com.example.canasta.data.remote.api

import com.example.canasta.data.remote.models.ArrayOfProducts
import com.example.canasta.data.remote.models.GetProduct
import com.example.canasta.data.remote.models.ProductRegistrationData
import retrofit2.http.*

/**
 * Servicio de API para operaciones relacionadas con productos
 */
interface ProductApiService {

    /**
     * Obtiene todos los productos
     * GET /products
     */
    @GET("products")
    suspend fun getProducts(): ArrayOfProducts

    /**
     * Crea un nuevo producto
     * POST /products
     * @param product Datos del producto a crear
     */
    @POST("products")
    suspend fun createProduct(@Body product: ProductRegistrationData): GetProduct

    /**
     * Obtiene un producto específico por su ID
     * GET /products/{productId}
     * @param productId ID del producto
     */
    @GET("products/{productId}")
    suspend fun getProduct(@Path("productId") productId: Long): GetProduct

    /**
     * Actualiza un producto existente
     * PUT /products/{productId}
     * @param productId ID del producto a actualizar
     * @param product Datos actualizados del producto
     */
    @PUT("products/{productId}")
    suspend fun updateProduct(
        @Path("productId") productId: Long,
        @Body product: ProductRegistrationData
    ): GetProduct

    /**
     * Elimina un producto
     * DELETE /products/{productId}
     * @param productId ID del producto a eliminar
     */
    @DELETE("products/{productId}")
    suspend fun deleteProduct(@Path("productId") productId: Long)
}

package com.example.canasta.data.remote.examples

import com.example.canasta.data.remote.ApiClient
import com.example.canasta.data.remote.models.CategoryReference
import com.example.canasta.data.remote.models.ProductRegistrationData
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.launch

/**
 * Ejemplo de uso de la capa de red de productos
 * 
 * IMPORTANTE: Este archivo es solo de referencia y no debe ser usado en producción.
 * Muestra cómo usar los servicios de API en tu código.
 */

// ============================================
// EJEMPLO 1: Establecer token de autenticación
// ============================================
fun setupAuthentication(token: String) {
    ApiClient.setAuthToken(token)
}

// ============================================
// EJEMPLO 2: Obtener todos los productos
// ============================================
fun fetchAllProducts(scope: CoroutineScope) {
    scope.launch {
        try {
            val products = ApiClient.productService.getProducts()

            // Procesar los productos
            products.forEach { product ->
                println("ID: ${product.id}")
                println("Nombre: ${product.name}")
                println("Categoría: ${product.category.name}")
                println("Metadata: ${product.metadata}")
                println("---")
            }

            // O puedes pasar los productos a tu UI
            // _uiState.value = UiState.Success(products)

        } catch (e: Exception) {
            // Manejar el error
            println("Error al obtener productos: ${e.message}")
            // _uiState.value = UiState.Error(e.message ?: "Error desconocido")
        }
    }
}

// ============================================
// EJEMPLO 3: Obtener un producto específico
// ============================================
fun fetchProductById(scope: CoroutineScope, productId: Long) {
    scope.launch {
        try {
            val product = ApiClient.productService.getProduct(productId)

            println("Producto encontrado:")
            println("ID: ${product.id}")
            println("Nombre: ${product.name}")
            println("Categoría: ${product.category.name}")

        } catch (e: Exception) {
            println("Error al obtener el producto: ${e.message}")
        }
    }
}

// ============================================
// EJEMPLO 4: Crear un nuevo producto
// ============================================
fun createNewProduct(
    scope: CoroutineScope,
    name: String,
    categoryId: Long,
    metadata: Map<String, String>? = null
) {
    scope.launch {
        try {
            val newProduct = ProductRegistrationData(
                name = name,
                category = CategoryReference(id = categoryId),
                metadata = metadata
            )

            val createdProduct = ApiClient.productService.createProduct(newProduct)

            println("Producto creado exitosamente:")
            println("ID: ${createdProduct.id}")
            println("Nombre: ${createdProduct.name}")
            println("Creado en: ${createdProduct.createdAt}")

        } catch (e: Exception) {
            println("Error al crear producto: ${e.message}")
        }
    }
}

// ============================================
// EJEMPLO 5: Actualizar un producto existente
// ============================================
fun updateExistingProduct(
    scope: CoroutineScope,
    productId: Long,
    newName: String,
    newCategoryId: Long,
    newMetadata: Map<String, String>? = null
) {
    scope.launch {
        try {
            val updateData = ProductRegistrationData(
                name = newName,
                category = CategoryReference(id = newCategoryId),
                metadata = newMetadata
            )

            val updatedProduct = ApiClient.productService.updateProduct(
                productId = productId,
                product = updateData
            )

            println("Producto actualizado:")
            println("ID: ${updatedProduct.id}")
            println("Nuevo nombre: ${updatedProduct.name}")
            println("Actualizado en: ${updatedProduct.updatedAt}")

        } catch (e: Exception) {
            println("Error al actualizar producto: ${e.message}")
        }
    }
}

// ============================================
// EJEMPLO 6: Eliminar un producto
// ============================================
fun deleteProduct(scope: CoroutineScope, productId: Long) {
    scope.launch {
        try {
            ApiClient.productService.deleteProduct(productId)
            println("Producto eliminado exitosamente")

        } catch (e: Exception) {
            println("Error al eliminar producto: ${e.message}")
        }
    }
}

// ============================================
// EJEMPLO 7: Manejo robusto de errores
// ============================================
fun fetchProductsWithErrorHandling(scope: CoroutineScope) {
    scope.launch {
        try {
            val products = ApiClient.productService.getProducts()
            // Éxito - actualizar UI
            println("${products.size} productos cargados")

        } catch (e: retrofit2.HttpException) {
            // Error HTTP específico
            when (e.code()) {
                401 -> {
                    println("No autorizado - Token inválido o expirado")
                    // Redirigir a login
                    ApiClient.setAuthToken(null)
                }
                403 -> println("Prohibido - No tienes permisos")
                404 -> println("Recurso no encontrado")
                500 -> println("Error del servidor")
                else -> println("Error HTTP ${e.code()}: ${e.message()}")
            }

        } catch (e: java.io.IOException) {
            // Error de red
            println("Error de conexión: ${e.message}")
            println("Verifica tu conexión a internet")

        } catch (e: kotlinx.serialization.SerializationException) {
            // Error al parsear JSON
            println("Error al procesar respuesta del servidor: ${e.message}")

        } catch (e: Exception) {
            // Cualquier otro error
            println("Error inesperado: ${e.message}")
        }
    }
}

// ============================================
// EJEMPLO 8: Buscar productos por nombre (usando filtrado local)
// ============================================
fun searchProducts(scope: CoroutineScope, query: String) {
    scope.launch {
        try {
            val allProducts = ApiClient.productService.getProducts()

            // Filtrar localmente
            val filteredProducts = allProducts.filter { product ->
                product.name.contains(query, ignoreCase = true)
            }

            println("Encontrados ${filteredProducts.size} productos que coinciden con '$query'")
            filteredProducts.forEach { product ->
                println("- ${product.name}")
            }

        } catch (e: Exception) {
            println("Error en búsqueda: ${e.message}")
        }
    }
}

// ============================================
// EJEMPLO 9: Obtener productos de una categoría específica
// ============================================
fun getProductsByCategory(scope: CoroutineScope, categoryName: String) {
    scope.launch {
        try {
            val allProducts = ApiClient.productService.getProducts()

            val productsInCategory = allProducts.filter { product ->
                product.category.name.equals(categoryName, ignoreCase = true)
            }

            println("Productos en categoría '$categoryName':")
            productsInCategory.forEach { product ->
                println("- ${product.name}")
            }

        } catch (e: Exception) {
            println("Error: ${e.message}")
        }
    }
}

// ============================================
// EJEMPLO 10: Crear múltiples productos en lote
// ============================================
fun createMultipleProducts(
    scope: CoroutineScope,
    products: List<Pair<String, Long>> // Lista de (nombre, categoryId)
) {
    scope.launch {
        val results = mutableListOf<String>()

        products.forEach { (name, categoryId) ->
            try {
                val productData = ProductRegistrationData(
                    name = name,
                    category = CategoryReference(id = categoryId)
                )

                val created = ApiClient.productService.createProduct(productData)
                results.add("✓ ${created.name} creado con ID ${created.id}")

            } catch (e: Exception) {
                results.add("✗ Error al crear $name: ${e.message}")
            }
        }

        println("Resultados:")
        results.forEach { println(it) }
    }
}

