/** * Barra de navegación inferior * @param currentRoute La ruta actual seleccionada * @param onNavigate Callback para navegar a una ruta */ @Composable fun BottomBar( currentRoute: AppDestinations, onNavigate: (Any) -> Unit ) { NavigationBar( containerColor = Primary, contentColor = Color.White ) { AppDestinations.entries.forEach { destination -> NavigationBarItem( selected = currentRoute == destination, onClick = { onNavigate(destination.route) }, icon = { Icon( imageVector = if (currentRoute == destination) destination.selectedIcon else destination.unselectedIcon, contentDescription = destination.label ) }, label = { Text(destination.label) }, colors = NavigationBarItemDefaults.colors( selectedIconColor = Color.White, selectedTextColor = Color.White, unselectedIconColor = Color.White.copy(alpha = 0.7f), unselectedTextColor = Color.White.copy(alpha = 0.7f), indicatorColor = Secondary ) ) } } }

