import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.tooling.preview.Preview
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import com.example.canasta.ui.components.common.BottomNavBar
import com.example.canasta.ui.components.settings.SettingsItem
import com.example.canasta.ui.components.settings.SettingsSection

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SettingsScreen(
    onBackClick: () -> Unit = {}
) {
    Scaffold(
        topBar = {
            TopAppBar(
                title = { },
                navigationIcon = {
                    IconButton(onClick = onBackClick) {
                        Icon(
                            imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                            contentDescription = "Volver",
                            tint = Color(0xFF333333)
                        )
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = Color.White
                )
            )
        },
        bottomBar = { BottomNavBar() }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .verticalScroll(rememberScrollState()),
            horizontalAlignment = Alignment.Start
        ) {
            // Título "Configuración" alineado a la izquierda
            Text(
                text = "Configuración",
                style = MaterialTheme.typography.headlineMedium,
                fontWeight = FontWeight.Bold,
                modifier = Modifier
                    .padding(start = 24.dp, top = 16.dp, bottom = 8.dp)
            )

            // Subtítulo
            Text(
                text = "Personaliza tu experiencia en Canasta",
                fontSize = 16.sp,
                color = Color(0xFF666666),
                modifier = Modifier
                    .padding(start = 24.dp, bottom = 24.dp)
            )

            // Sección: Cuenta
            SettingsSection(
                title = "Cuenta",
                icon = {
                    Box(
                        modifier = Modifier
                            .size(40.dp)
                            .clip(CircleShape)
                            .background(Color(0xFF4A7C4E)),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = Icons.Default.AccountCircle,
                            contentDescription = null,
                            tint = Color.White,
                            modifier = Modifier.size(24.dp)
                        )
                    }
                }
            ) {
                SettingsItem(
                    title = "Cambiar contraseña",
                    subtitle = "Actualiza tu contraseña de acceso",
                    onClick = { /* TODO: Navegar a cambiar contraseña */ }
                )

                Spacer(modifier = Modifier.height(12.dp))

                SettingsItem(
                    title = "Cambiar idioma",
                    subtitle = "Selecciona tu idioma preferido",
                    onClick = { /* TODO: Navegar a cambiar idioma */ }
                )
            }

            Spacer(modifier = Modifier.height(24.dp))
        }
    }
}

